  '{"logoUrl":"","primary":"#7c3aed","secondary":"#f59e0b","accent":"#10b981","background":"#1e1b4b","backgroundImageUrl":"","bannerImageUrl":"","bannerText":"Play. Climb. Win!","sponsorLogos":[]}'::jsonb,
  '{"headline":"Snake & Ladder Promo","tagline":"Race to 100 and win exclusive prizes!","welcomeMessage":"Join a room with up to 10 players. Take turns rolling the dice on one shared board — climb the ladders, dodge the snakes and be the first to reach 100!","mechanics":["Type your name and join a room using the code, link or QR.","Tap READY. The host starts the game once everyone is ready.","When it''s your turn, tap ROLL. If time runs out, the computer rolls for you.","Ladders take you up, snakes slide you down. First to reach 100 wins!"],"prizeTitle":"Grand Prize","prizeDetails":"Winners receive an exclusive discount voucher. Show your winning code at our store or use it online.","winnerMessage":"Congratulations! You conquered the board!","loserMessage":"So close! Thanks for playing — here is something for you anyway.","privacyNotice":"We collect the information you enter (nickname and any registration details) only to run this promo, announce winners and send prizes. Marketing messages are sent only if you tick the consent box. You can ask us to delete your data at any time. Registration data is automatically anonymised after the retention period of this campaign.","consentText":"Yes, send me news, promos and offers. (Optional — you can still play without ticking this.)"}'::jsonb,
