  '{"enabled":false,"fields":[{"key":"name","label":"Full name","type":"text","enabled":true,"required":false},{"key":"email","label":"Email","type":"email","enabled":true,"required":false},{"key":"phone","label":"Mobile number","type":"tel","enabled":true,"required":false},{"key":"city","label":"City","type":"text","enabled":false,"required":false}],"consentEnabled":true}'::jsonb,
  '[{"id":"facebook","label":"Visit Our Facebook Page","url":"https://facebook.com","style":"primary","showOn":["landing","lobby","finish"]},{"id":"website","label":"Visit Our Website","url":"https://example.com","style":"outline","showOn":["landing","finish"]},{"id":"reward","label":"Claim Your Reward","url":"https://example.com/rewards","style":"secondary","showOn":["finish"]}]'::jsonb,
